Outcome<MomentOwnerSource>read_visit_appointment_director_command_effect_world(const WorldBundle&before,const WorldBundle&after,const StableId&actor,const ReceiptDetails&details,const VisitAppointmentMeetingTime2Context*actual){auto valid=enabled(after);if(!valid.ok)return {false,{},valid.error};if(before.catalog.get()!=after.catalog.get()||!before.interaction.visit_appointment_invitations)return {false,{},common_failure("VisitAppointmentActualCandidateDeltaRequired",{},ErrorKind::internal).error};ExactRead exact;valid=exact.prepare(after,actual);if(!valid.ok)return {false,{},valid.error};if(!exact.context||!exact.context->invitation_history.actual_commands)return {false,{},common_failure("VisitAppointmentDirectorCommandSourcesRequired",{},ErrorKind::unsupported_capability).error};const auto&x=*exact.context;valid=validate_visit_appointments(after.common,*after.catalog->common,*after.interaction.visit_messages,*after.catalog->interaction->visit_messages,*after.catalog->personal_appointments,*after.interaction.personal_appointments,*after.catalog->interaction,*after.catalog->visit_appointment_invitations,*after.interaction.visit_appointment_invitations,x.invitation_history,after.catalog->visit_message_replies.get());if(!valid.ok)return {false,{},valid.error};auto at=after.actual_phase_moment();if(!at.ok)return {false,{},at.error};return read_visit_appointment_director_command_effect(after.common,*before.interaction.visit_appointment_invitations,*after.interaction.visit_appointment_invitations,actor,details,at.value);}
