Status finalize_visit_appointment_director_actor_result_world(const WorldBundle&w,const DirectorAdoptionResult2&adoption,const VisitAppointmentMeetingTime2Context*actual){if(!adoption.accepted_command)return common_failure("VisitAppointmentActualAdoptionRequired",{},ErrorKind::internal);const auto&c=*adoption.accepted_command;const auto&r=c.actual_effect.source_ref;if(r.domain!=visit_appointment_module)return common_success();auto valid=validate_visit_appointment_director_actor_effect_world(w,c.actor_id,r,actual);if(!valid.ok)return valid;ExactRead exact;valid=exact.prepare(w,actual);if(!valid.ok)return valid;auto joined=read_visit_authored_command(*exact.context->invitation_history.actual_commands,c.actual_effect,c.actor_id,c.command_kind,c.accepted_at.half_day_tick);if(!joined.ok)return {false,{},joined.error};return joined.value.decision==&adoption?common_success():common_failure("VisitAppointmentForeignAdoption",r.id,ErrorKind::internal);}

